//! File system interface for entity search ingestion

use std::{
    io::ErrorKind,
    path::{self, Path, PathBuf},
    time::SystemTime,
};

use arrow::datatypes::{DataType, Field, Schema};
use tokio::fs;
use uuid::Uuid;

use crate::domain::{
    models::entity_ingestion::IngestionKey,
    repositories::entity_ingestion::EntitySearchPipelineError,
};

/// File system pipeline
#[derive(Clone)]
pub struct ExposedDataPipeline {
    root: PathBuf,
    key: PipelineKey,
    fs_schema: FsSchema,
}

#[derive(Clone)]
pub struct PipelineKey(Uuid);

impl PipelineKey {
    pub fn new() -> Self {
        Self(Uuid::now_v7())
    }
}

impl From<&PipelineKey> for IngestionKey {
    fn from(value: &PipelineKey) -> Self {
        Self::new(value.0)
    }
}

impl From<IngestionKey> for PipelineKey {
    fn from(value: IngestionKey) -> Self {
        Self(value.uuid())
    }
}

#[derive(Clone)]
struct FsSchema {
    raw: String,
    // cleaned: String,
    // resolved: String,
}

impl Default for FsSchema {
    fn default() -> Self {
        Self {
            raw: "raw".into(),
            // cleaned: "cleaned".into(),
            // resolved: "resolved".into(),
        }
    }
}

impl ExposedDataPipeline {
    /// Opens an existing raw declaration dataset without creating directories.
    ///
    /// # Errors
    /// Returns a read error for a missing or invalid declaration directory.
    pub fn open_existing_declarations(
        root: &Path,
        key: IngestionKey,
    ) -> Result<Self, EntitySearchPipelineError> {
        let root = path::absolute(root).map_err(|e| read_error(root, e))?;
        let directory = root.join(key.to_string()).join("raw/declarations");
        if !std::fs::metadata(&directory)
            .map_err(|e| read_error(&directory, e))?
            .is_dir()
        {
            return Err(read_error(&directory, "expected a declaration directory"));
        }
        Ok(Self {
            root,
            key: PipelineKey::from(key),
            fs_schema: FsSchema::default(),
        })
    }

    /// Opens an existing cleaned declaration dataset without requiring retained raw partitions.
    ///
    /// # Errors
    /// Returns a read error when the cleaned declaration directory is missing.
    pub fn open_cleaned_declarations(
        root: &Path,
        key: IngestionKey,
    ) -> Result<Self, EntitySearchPipelineError> {
        let root = path::absolute(root).map_err(|error| read_error(root, error))?;
        let directory = root.join(key.to_string()).join("cleaned/declarations");
        if !std::fs::metadata(&directory)
            .map_err(|error| read_error(&directory, error))?
            .is_dir()
        {
            return Err(read_error(
                &directory,
                "expected cleaned declaration directory",
            ));
        }
        Ok(Self {
            root,
            key: PipelineKey::from(key),
            fs_schema: FsSchema::default(),
        })
    }

    /// Opens an existing run with retained raw, cleaned, and resolved declaration data.
    ///
    /// # Errors
    /// Returns a read error when any required stage directory is missing.
    pub fn open_resolved_declarations(
        root: &Path,
        key: IngestionKey,
    ) -> Result<Self, EntitySearchPipelineError> {
        let pipeline = Self::open_cleaned_declarations(root, key)?;
        let required = [
            pipeline.raw_path().join("declarations"),
            pipeline.resolved_declarations_path(),
        ];
        for directory in required {
            if !std::fs::metadata(&directory)
                .map_err(|error| read_error(&directory, error))?
                .is_dir()
            {
                return Err(read_error(
                    &directory,
                    "expected declaration pipeline directory",
                ));
            }
        }
        Ok(pipeline)
    }

    pub(super) fn resolved_declarations_path(&self) -> PathBuf {
        self.latest_run_path().join("resolved/declarations")
    }

    pub(super) fn cleaned_declarations_path(&self) -> PathBuf {
        self.latest_run_path().join("cleaned/declarations")
    }

    /// Returns the absolute path and key of the most recently modified run directory.
    /// Equal timestamps use the greatest UUID. An absent or empty store returns `None`.
    /// This operation does not create or change files.
    ///
    /// # Errors
    /// Returns an error if ingestion storage cannot be read.
    pub async fn latest_ingestion(
        root: &Path,
    ) -> Result<Option<(PathBuf, IngestionKey)>, EntitySearchPipelineError> {
        let root = path::absolute(root).map_err(|e| read_error(root, e))?;
        let mut entries = match fs::read_dir(&root).await {
            Ok(entries) => entries,
            Err(error) if error.kind() == ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(read_error(&root, error)),
        };
        let mut latest: Option<(SystemTime, PathBuf, IngestionKey)> = None;
        while let Some(entry) = entries
            .next_entry()
            .await
            .map_err(|e| read_error(&root, e))?
        {
            let path = entry.path();
            if !entry
                .file_type()
                .await
                .map_err(|e| read_error(&path, e))?
                .is_dir()
            {
                continue;
            }
            let Some(key) = entry
                .file_name()
                .to_str()
                .and_then(|name| name.parse::<IngestionKey>().ok())
            else {
                continue;
            };
            let modified_at = entry
                .metadata()
                .await
                .and_then(|metadata| metadata.modified())
                .map_err(|e| read_error(&path, e))?;
            if latest.as_ref().is_none_or(|(latest_time, _, latest_key)| {
                (modified_at, key.uuid()) > (*latest_time, latest_key.uuid())
            }) {
                latest = Some((modified_at, path, key));
            }
        }
        Ok(latest.map(|(_, path, key)| (path, key)))
    }

    /// Creates a new instance of [`ExposedDataPipeline`] with an [`IngestionKey`]
    ///
    /// # Errors
    /// - if [`root`] cannot be parsed as absolute
    /// - if required directories cannot be created
    pub fn new_with_ingestion_key(
        root: &PathBuf,
        key: IngestionKey,
    ) -> Result<Self, EntitySearchPipelineError> {
        let root_abs = path::absolute(root).map_err(|_| {
            EntitySearchPipelineError::Unexpected("valid root path must be provided".to_string())
        })?;

        let res = Self {
            root: root_abs,
            key: PipelineKey::from(key),
            fs_schema: FsSchema::default(),
        };
        std::fs::create_dir_all(res.raw_path()).map_err(|_| {
            EntitySearchPipelineError::Unexpected("must be able to create fs paths".to_string())
        })?;
        Ok(res)
    }

    fn latest_run_path(&self) -> PathBuf {
        self.root.join(self.key.0.to_string())
    }

    pub(super) fn raw_path(&self) -> PathBuf {
        self.latest_run_path().join(&self.fs_schema.raw)
    }

    pub(super) const fn key(&self) -> &PipelineKey {
        &self.key
    }

    // pub(super) fn cleaned_path(&self) -> PathBuf {
    //     self.latest_run_path().join(&self.fs_schema.cleaned)
    // }
    //
    // pub(super) fn resolved_path(&self) -> PathBuf {
    //     self.latest_run_path().join(&self.fs_schema.resolved)
    // }
}

fn read_error(path: &Path, error: impl std::fmt::Display) -> EntitySearchPipelineError {
    EntitySearchPipelineError::ReadError(format!("{}: {error}", path.display()))
}

pub(super) fn members_schema() -> Schema {
    let pmi = Field::new("parliament_member_id", DataType::UInt32, false);
    let n = Field::new("name", DataType::Utf8, false);
    let pi = Field::new("party_id", DataType::UInt32, false);
    let pn = Field::new("party_name", DataType::Utf8, false);
    let c = Field::new("constituency", DataType::Utf8, false);
    Schema::new(vec![pmi, n, pi, pn, c])
}
//! CLI inbound port

use std::{path::PathBuf, str::FromStr};

use clap::{Parser, Subcommand};

use crate::{
    domain::{
        models::entity_ingestion::{
            DeclarationIngestionStage, EntityIngestionRequest, IngestionKey, MemberIngestionStage,
        },
        services::declaration_cleaning::DeclarationCleanerService,
        services::declaration_fetch::DeclarationFetcherService,
        services::declaration_loading::DeclarationLoaderService,
        services::declaration_resolution::DeclarationResolverService,
        services::entity_ingestion::{
            EntityFetcherService, EntityIngesterService, FetcherService, IngesterService,
        },
    },
    inbound::cli::config::{
        DataConfig, DeclarationFetcherConfig, DeclarationResolverConfig, FetcherConfig,
        LoaderConfig,
    },
    outbound::{ExposedDataPipeline, ExposedDatabase, ParliamentApiClient, SplinkScorer},
};

pub mod config;

/// CLI Data Args
#[derive(Parser)]
pub struct DataArgs {
    #[command(subcommand)]
    command: DataCommands,
}

/// CLI Subcommands
#[derive(Subcommand)]
#[allow(missing_docs)]
pub enum DataCommands {
    /// Show the latest ingestion key and directory path.
    Latest {
        /// YAML configuration with the ingestion `data_dir`.
        config: PathBuf,
    },
    Declarations {
        /// Stage to run: fetch, clean, resolve, or load.
        #[arg(value_parser = ["fetch", "clean", "resolve", "load"])]
        stage: String,
        /// YAML configuration containing the declaration `data_dir`.
        config: PathBuf,
        /// Ingestion run to clean, resolve, or load.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    Members {
        stage: String,
        config: PathBuf,
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
}

/// Entry point for CLI commands
///
/// # Errors
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> anyhow::Result<()> {
    match args.command {
        DataCommands::Latest { config } => {
            let config = LoaderConfig::try_from(&config)?;
            match ExposedDataPipeline::latest_ingestion(&config.data_dir).await? {
                Some((path, key)) => {
                    println!("Ingestion key: {key}");
                    println!("Path: {}", path.display());
                }
                None => println!("No ingestion runs found."),
            }
        }
        DataCommands::Declarations {
            stage,
            config,
            ingestion_key,
        } => match DeclarationIngestionStage::from_str(&stage)? {
            DeclarationIngestionStage::Fetch => {
                let config = DeclarationFetcherConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let api = ParliamentApiClient::new(config.batch_size)?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let fs = ExposedDataPipeline::new_with_ingestion_key(
                    &config.data_dir,
                    ingestion_key.unwrap_or_default(),
                )?;
                DeclarationFetcherService::new(db, api, fs)
                    .fetch_declarations()
                    .await?;
            }
            DeclarationIngestionStage::Resolve => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations resolve requires --ingestion-key")
                })?;
                let config = DeclarationResolverConfig::try_from(&config)?;
                let storage = ExposedDataPipeline::open_cleaned_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let scorer = SplinkScorer::new(config.resolution_python, config.resolution_worker)?;
                let summary =
                    DeclarationResolverService::new(storage, scorer, config.candidate_budget)
                        .resolve_declarations()
                        .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Resolved declarations: {}",
                    std::path::absolute(config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("resolved/declarations")
                        .display()
                );
                println!("Observations: {}", summary.observations);
                println!("Funding occurrences: {}", summary.payments);
                println!("Pair decisions: {}", summary.pairs);
            }
            DeclarationIngestionStage::Load => {
                let ingestion_key = ingestion_key
                    .ok_or_else(|| anyhow::anyhow!("declarations load requires --ingestion-key"))?;
                let config = LoaderConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let storage = ExposedDataPipeline::open_resolved_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let summary = DeclarationLoaderService::new(storage, db)
                    .load_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                match summary.outcome {
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::Imported => {
                        println!("Loaded declarations: {}", summary.declarations);
                    }
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::AlreadyLoaded => {
                        println!("Run already loaded. Declarations: {}", summary.declarations);
                    }
                }
                println!("Resolved identities: {}", summary.funders);
                println!("Funding occurrences: {}", summary.funding_entries);
            }
            DeclarationIngestionStage::Clean => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations clean requires --ingestion-key")
                })?;
                let config = LoaderConfig::try_from(&config)?;
                let fs = ExposedDataPipeline::open_existing_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let summary = DeclarationCleanerService::new(fs)
                    .clean_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Cleaned declarations: {}",
                    std::path::absolute(&config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("cleaned/declarations")
                        .display()
                );
                println!("Member partitions: {}", summary.member_partitions);
                println!("Declarations: {}", summary.declarations);
                println!("Funding entries: {}", summary.funding_entries);
                println!("Funder observations: {}", summary.funders);
            }
        },
        DataCommands::Members {
            stage,
            config,
            ingestion_key,
        } => {
            let stage = MemberIngestionStage::from_str(&stage)?;
            let ingestion_key = ingestion_key.unwrap_or_default();
            match stage {
                MemberIngestionStage::Fetch => {
                    let config = FetcherConfig::try_from(&config)?;
                    let api = ParliamentApiClient::new(config.batch_size)?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let service = FetcherService::new(fs, api);

                    let req = EntityIngestionRequest {};
                    service.fetch_members(&req).await?;
                }
                MemberIngestionStage::Load => {
                    let config = LoaderConfig::try_from(&config)?;
                    let data_config = DataConfig::from_env()?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let db = ExposedDatabase::new(&data_config.connection_string).await;
                    let service = IngesterService::new(fs, db);

                    service.load_members().await?;
                }
            }
        }
    }
    Ok(())
}
//! Contains entity ingestion models

use std::{fmt::Display, str::FromStr};

// use std::str::FromStr;
//
use strum::EnumString;
use thiserror::Error;
use uuid::Uuid;

use crate::domain::repositories::{
    entity_ingestion::EntitySearchPipelineError, parliament_api::ParliamentApiError,
};

/// Data required to search entities
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EntityIngestionRequest;

/// Key used for ingestion
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct IngestionKey(Uuid);

impl Display for IngestionKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.0.to_string().as_str())
    }
}

impl FromStr for IngestionKey {
    type Err = EntityIngestionError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let id =
            Uuid::from_str(s).map_err(|e| EntityIngestionError::InvalidStage(e.to_string()))?;
        Ok(Self(id))
    }
}

impl IngestionKey {
    /// Creates a new key
    #[must_use]
    pub const fn new(uuid: Uuid) -> Self {
        Self(uuid)
    }

    /// Underlying UUID
    #[must_use]
    pub const fn uuid(&self) -> Uuid {
        self.0
    }
}

impl Default for IngestionKey {
    fn default() -> Self {
        Self::new(Uuid::now_v7())
    }
}

/// From what stage to run in the Member pipeline
#[derive(Clone, Debug, PartialEq, Eq, EnumString)]
#[allow(missing_docs)]
#[strum(ascii_case_insensitive)]
pub enum MemberIngestionStage {
    Fetch,
    Load,
}
/// Supported acquisition stage for declarations.
#[derive(Clone, Debug, PartialEq, Eq, EnumString)]
#[strum(ascii_case_insensitive)]
pub enum DeclarationIngestionStage {
    /// Capture source evidence for later offline processing.
    Fetch,
    /// Split captured funding occurrences and funder observations offline.
    Clean,
    /// Resolve cleaned funder observations and attribute each occurrence.
    Resolve,
    /// Load the published identities and attributions into the database.
    Load,
}

/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntityIngestionError {
    /// Errors related to the parliament API
    #[error("error when retrieving data from the parliament API: {0}")]
    ApiError(#[from] ParliamentApiError),

    /// Generic error related to entity parsing, cleaning and resolution
    #[error("error in ingestion pipeline: {0}")]
    DataError(String),

    /// Failure reading or writing ingestion storage.
    #[error("ingestion storage failed: {0}")]
    IoError(#[from] EntitySearchPipelineError),

    /// Invalid stage
    #[error("invalid stage provided: {0}")]
    InvalidStage(String),

    /// Invalid stage
    #[error("invalid ingestion ID: {0}")]
    UnvalidIngestionId(String),

    /// Generic error
    #[error("unexpected error occured: {0}")]
    UnexpectedError(String),
}

